def solve(record):
    x = record['record_2']
    edges, source, target = x[0], x[1], x[2]

    if source == target:
        # A self-transfer (route ending where it starts) needs a
        # positive-length round trip: shortest cycle/walk back to source.
        has_self_loop = False
        extends = []
        for u, v in edges:
            if u == target and v == target:
                has_self_loop = True
            elif u == target or v == target:
                extends.append(v if u == target else u)
        if has_self_loop:
            return 1
        if extends:
            return 2  # go to a neighbor and come back
        return -1

    adjacency = {}
    for u, v in edges:
        if u == v:
            continue  # self-loops never shorten a route between distinct ends
        adjacency.setdefault(u, set()).add(v)
        adjacency.setdefault(v, set()).add(u)

