            name, points = row[0], row[1]
        except (TypeError, IndexError):
            continue
        try:
            pts = float(points)
        except (TypeError, ValueError):
            continue
        if pts > 0:
            qualified.append((name, pts))

    if not qualified:
        return []

    # Sort by descending points, then ascending name
