    stack = []
    for comp in x.split('/'):
        if comp == '':
            # Repeated slashes yield empty separators; ignore them.
            continue
        elif comp == '.':
            # Literal single-dot component is kept as a plain component.
            stack.append('.')
        elif comp == '..':
            # Pop the previous component unless it is itself an excess '..';
            # otherwise the '..' is excess and preserved.
            if stack and stack[-1] != '..':
                stack.pop()
            else:
                stack.append('..')
        else:
            # Regular component: preserved as-is, keeping case.
            stack.append(comp)

    return stack
